LIMIT = 3
paid = set()
def give(user):
    if user in paid:
        return f"{user}: 이미 받음 — 지급 안 함"
    if len(paid) >= LIMIT:
        return f"{user}: 선착순 마감"
    paid.add(user)
    return f"{user}: {len(paid)}번째 지급"
for u in ["A", "A", "B", "C", "D"]:
    print(give(u))

calls = [("s1", False)] * 9 + [("s2", True)]
per = {}
for srv, fail in calls:
    n, f = per.get(srv, (0, 0))
    per[srv] = (n + 1, f + fail)
def verdict(f, n):
    return "→ 서킷 열림" if f / n >= 0.5 else "→ 닫힘"
for srv, (n, f) in sorted(per.items()):
    print(srv, f"{f}/{n} 실패율 {f/n:.0%}", verdict(f, n))
tn = sum(n for n, _ in per.values())
tf = sum(f for _, f in per.values())
print("전체", f"{tf}/{tn} 실패율 {tf/tn:.0%}", verdict(tf, tn))
